/// The onset-rhyme rules of spec 3.3 to 3.12, written once as predicates. The tables in
/// `SyllableTables` are generated by evaluating these predicates over the inventory; nothing else
/// encodes spelling rules (ENG-R302: the coda rules are those of the table, 3.6).
///
/// Where 3.12 is open to more than one reading, the reading that reproduces the reference counts of
/// 3.15 is used; each such reading is listed in docs/decisions/0100-engine-syllable-counts.md.
package enum SyllableRules {
    private static let standard = Set(RhymeInventory.standard)
    private static let afterQu = Set(RhymeInventory.afterQu)
    private static let afterQuExtended = Set(RhymeInventory.afterQuExtended)
    private static let afterGiExtra = Set(RhymeInventory.afterGiExtra)
    private static let extendedExtra = Set(RhymeInventory.extendedExtra)

    /// Whether `rhyme` may follow `onset`. `extended: false` asks for Tier A, `extended: true` for
    /// Tier B (which includes Tier A). Tones are checked separately (`Rhyme.accepts`, 3.11).
    package static func allows(_ onset: Onset, _ rhyme: Rhyme, extended: Bool) -> Bool {
        guard let onsetTier = onset.tier, extended || onsetTier == .standard else { return false }
        let spelling = rhyme.spelling
        switch onset {
        case .qu:
            // 3.8, ENG-R311: the rhyme list after `qu`; Tier B adds exactly `o` and `ơn`.
            return afterQu.contains(spelling) || (extended && afterQuExtended.contains(spelling))
        case .gi:
            return allowsAfterGi(rhyme, extended: extended)
        default:
            if rhyme.coda == .k {
                // 3.6, 3.12: Tier B `k` coda as a spelling variant of a `c` rhyme (`Đắk`, `Lắk`, `Búk`).
                guard extended, let cRhyme = cVariant(of: rhyme) else { return false }
                return allowsAfterOrdinaryOnset(onset, cRhyme, extended: true)
            }
            guard standard.contains(spelling) || (extended && extendedExtra.contains(spelling)) else { return false }
            return allowsAfterOrdinaryOnset(onset, rhyme, extended: extended)
        }
    }

    /// The `c` rhyme that a Tier B `k` rhyme is a spelling variant of (`ăk` -> `ăc`), if it exists
    /// among the rhymes after ordinary onsets (3.7 and the Tier B extra rhymes).
    package static func cVariant(of rhyme: Rhyme) -> Rhyme? {
        guard rhyme.coda == .k else { return nil }
        let spelling = String(rhyme.spelling.dropLast()) + "c"
        guard standard.contains(spelling) || extendedExtra.contains(spelling) else { return nil }
        return Rhyme(id: -1, spelling: spelling)
    }

    /// ENG-R305: every Tier A rhyme that does not start with `i`, `y` or a medial glide, plus `êc` and
    /// `êng`. Tier B adds the medial rhymes with `o` (`gioăng`) and the non-medial extra rhymes.
    private static func allowsAfterGi(_ rhyme: Rhyme, extended: Bool) -> Bool {
        let spelling = rhyme.spelling
        if afterGiExtra.contains(spelling) { return true }
        if rhyme.letters[0] == .i || rhyme.letters[0] == .y { return false }
        if rhyme.isMedial { return extended && rhyme.hasOMedial }
        return standard.contains(spelling) || (extended && extendedExtra.contains(spelling))
    }

    /// Spelling constraints for every onset other than `qu` and `gi` (3.3, 3.4, 3.10, 3.12).
    private static func allowsAfterOrdinaryOnset(_ onset: Onset, _ rhyme: Rhyme, extended: Bool) -> Bool {
        let spelling = rhyme.spelling
        // ENG-R313: `yê…` only with no onset; with no onset `iê…` is invalid (`ia` is valid).
        if rhyme.starts(with: "yê"), onset != .none { return false }
        if onset == .none, rhyme.starts(with: "iê") { return false }
        // ENG-R314: open `y` is Tier A only with no onset or after `h k l m s t th v`.
        if spelling == "y", !extended, !RhymeInventory.openYStandardOnsets.contains(onset) { return false }
        // ENG-R315: `uơ` is Tier A only after `h` and `th`.
        if spelling == "uơ", !extended, !RhymeInventory.uoStandardOnsets.contains(onset) { return false }
        // 3.4, ENG-R312: no medial glide after `c k gh ngh`; after labials only in Tier B.
        if rhyme.isMedial {
            if onset.forbidsMedial { return false }
            if onset.isLabial, !extended { return false }
        }
        switch onset {
        case .k, .gh, .ngh:
            // ENG-R310: only before `e ê i y iê ia`; Tier B allows `k` before any vowel.
            if !rhyme.isFront { return extended && onset == .k }
        case .c, .ng:
            // ENG-R310: never before `e ê i y iê ia`.
            if rhyme.isFront { return false }
        case .g:
            // 3.3: not before `e ê iê ia y`; an `i` rhyme after `g` is the `gì` case (ENG-R306).
            let first = rhyme.letters[0]
            if first == .e || first == .eCircumflex || first == .y { return false }
            if rhyme.starts(with: "ia") || rhyme.starts(with: "iê") { return false }
        default:
            break
        }
        return true
    }
}
